INSERT INTO cw_refund
    (tenant_id, refund_no, order_id, type, status, amount, reason, new_spec, created_at_ms)
SELECT #{record.tenantId}, #{record.refundNo}, o.order_id, #{record.type}, #{record.status},
       #{record.amount}, #{record.reason}, #{record.newSpec}, #{record.createdAtMs}
FROM cw_order o
WHERE o.tenant_id = #{record.tenantId}
  AND CAST(o.user_id AS BINARY) = CAST(#{userId} AS BINARY) AND o.order_id = #{record.orderId}
